ALTER TABLE "param_weight"
ADD FOREIGN KEY("param_set_type_id") REFERENCES "param_set_type"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "data_workout"
ADD FOREIGN KEY("user_id") REFERENCES "param_users"("id")
